            zusatz={`Spanne ${geld(r.spanne.min)} – ${geld(r.spanne.max)}`}
            rechts={<AmpelMarke ampel={r.ampel} className={r.ampel === "kritisch" ? "bg-white/10 ring-white/25" : undefined} />}
          >
